// ---------------------------------------------------------------------------------------------
// gateOpen head override (P1) + runOpenPr product-shape delegation failure signalling (P2)
// ---------------------------------------------------------------------------------------------
const { gateOpen } = await import('./gate.mjs');
const { branchExists } = await import('./platform.mjs');
const { runOpenPr } = await import('./openpr.mjs');

// A Product with a platform + an epic whose ledger has a stories review step, on a bare-remote git repo.
function productWithStoriesStep() {
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-gopen-'));
  git(T, 'init', '-q'); git(T, 'config', 'user.email', 'a@b.c'); git(T, 'config', 'user.name', 'x');
  fs.mkdirSync(path.join(T, '.sdlc'), { recursive: true });
  fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({ platform: 'github', default_branch: 'main', roster: [] }));
  fs.mkdirSync(path.join(T, 'epics/EP-demo/.sdlc'), { recursive: true });
  fs.writeFileSync(path.join(T, 'epics/EP-demo/.sdlc/state.json'), JSON.stringify({
    currentStep: 'stories-review',
    steps: [{ id: 'stories-review', type: 'review+approve', artifact: 'stories/', status: 'in_review', risk_tags: [] }],
  }));
  fs.writeFileSync(path.join(T, 'epics/EP-demo/epic.md'), '---\nowner: x\nrepos: []\n---\n');
  return T;
}

test('gateOpen: opens the PR against the head override, not its recomputed per-story branch (P1)', async () => {
  const T = productWithStoriesStep();
  let seenHead;
  const creator = (_platform, opts) => { seenHead = opts.head; return { ok: true, url: 'https://x/pr/1' }; };
  // a per-story review: artifact collapses to stories/, but the pushed head is the -S01 branch
  const res = await gateOpen(T, { epic: 'EP-demo', artifact: 'stories/', head: 'review/EP-demo/stories-S01', creator });
  assert.equal(seenHead, 'review/EP-demo/stories-S01'); // NOT review/EP-demo/stories
  assert.equal(res.url, 'https://x/pr/1');
  assert.deepEqual([res.opened, res.branch, res.step], [true, 'review/EP-demo/stories-S01', 'stories-review']);
  fs.rmSync(T, { recursive: true, force: true });
});

test('gateOpen: re-opening a review on a new PR stamps the OLD number on older approvals first, so a re-approval can go live (E62 review)', async () => {
  const { T, ep } = scaffoldEpic();
  try {
    git(T, 'init', '-q'); git(T, 'config', 'user.email', 'a@b.c'); git(T, 'config', 'user.name', 'x');
    const productConfig = JSON.parse(fs.readFileSync(path.join(T, '.sdlc/hub.json'), 'utf8'));
    fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({ ...productConfig, platform: 'gitlab' }));
    // approvals recorded before PR provenance existed: no `pr`, bound to content that has since changed
    fs.writeFileSync(path.join(ep, '.sdlc/approvals.json'), JSON.stringify([
      { artifact: 'architecture.md', step: 'architecture-review', approver: 'al', status: 'approved', date: '2026-06-01', source: 'bridge', artifactHash: 'sha256:old', approvedAt: '2026-06-01', engagement: 'none' },
    ]));
    // The group path holds a number too: the PR number is read from its own segment, never the first number.
    const creator = () => ({ ok: true, url: 'https://gitlab.example/123/p/-/merge_requests/9' });
    await captureConsole(() => gateOpen(T, { epic: 'EP-test', artifact: 'architecture.md', creator, hasBranch: () => true }));
    const stamped = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json'), 'utf8'));
    assert.equal(stamped[0].pr, 7, 'the approval is stamped with the PR it came from, before the pointer moves');
    assert.equal(JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/hub-prs.json'), 'utf8'))[0].number, 9);
    // the same person approves again on #9 (GitLab: no submission time) — it is a new review, so it goes live
    const { gateSync: sync } = await import('./gate.mjs');
    await captureConsole(() => sync(T, { epic: 'EP-test', today: '2026-09-16',
      reader: () => ({ ok: true, state: 'opened', merged: false, reviews: [{ login: 'al', state: 'APPROVED' }], threads: [] }) }));
    const after = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json'), 'utf8'));
    assert.equal(after.find((a) => a.approver === 'al').artifactHash, artifactHash(ep, 'architecture.md'), 'a re-approval on the new MR is live');
  } finally { fs.rmSync(T, { recursive: true, force: true }); }
});

