test('gateOpen: requests NO reviewers, still labels the touched domain (E62, BUG-3)', async () => {
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-gopen2-'));
  git(T, 'init', '-q'); git(T, 'config', 'user.email', 'a@b.c'); git(T, 'config', 'user.name', 'x');
  fs.mkdirSync(path.join(T, '.sdlc'), { recursive: true });
  // A roster with a reviewer and a repos.json domain owner — both left on disk from an older release.
  // Before E62 both were requested; now neither is read.
  fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({
    platform: 'github', default_branch: 'main',
    roster: [{ login: 'bo', name: 'bob', roles: { hub: ['reviewer'] } }, { login: 'ca', name: 'carol' }],
  }));
  fs.writeFileSync(path.join(T, '.sdlc/repos.json'), JSON.stringify({ repos: [{ name: 'backend', domain_owner: 'carol' }] }));
  fs.mkdirSync(path.join(T, 'epics/EP-demo/.sdlc'), { recursive: true });
  fs.writeFileSync(path.join(T, 'epics/EP-demo/.sdlc/state.json'), JSON.stringify({
    currentStep: 'stories-review',
    steps: [{ id: 'stories-review', type: 'review+approve', artifact: 'stories/', status: 'in_review', risk_tags: [] }],
  }));
  fs.writeFileSync(path.join(T, 'epics/EP-demo/epic.md'), '---\nowner: x\nrepos: [backend]\n---\n');
  fs.mkdirSync(path.join(T, 'epics/EP-demo/stories'), { recursive: true });
  fs.writeFileSync(path.join(T, 'epics/EP-demo/stories/EP-demo-S01.md'), '---\nrepos: [backend]\n---\n');
  let seen;
  const creator = (_p, opts) => { seen = opts; return { ok: true, url: 'https://x/pr/1' }; };
  const { out } = await captureConsole(() => gateOpen(T, { epic: 'EP-demo', artifact: 'stories/', creator }));
  assert.equal(seen.reviewers, undefined, 'no reviewer is requested — there is no roster to choose them from');
  assert.match(out, /no reviewers were requested — ask them on the PR itself/, 'and the opener is told so');
  assert.deepEqual(seen.labels, ['domain:backend']);     // the stories review still labels the touched repos
  fs.rmSync(T, { recursive: true, force: true });
});

test('runOpenPr: a product-shape delegation that opens no PR sets a non-zero exit code (P2)', async () => {
  const prev = process.exitCode;
  const T = productWithStoriesStep();
  let bare;
  try {
    // bare remote so the branch push succeeds; Product platform null so the delegated gateOpen reaches its
    // local "no PR opened" path and returns no url (that path does NOT set exitCode itself, so the
    // exit code can only come from runOpenPr's P2 line — i.e. the test is mutation-proof for the fix).
    bare = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-bare-')); git(bare, 'init', '-q', '--bare');
    fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({ platform: null, default_branch: 'main', roster: [] }));
    fs.writeFileSync(path.join(T, 'seed.txt'), '0'); git(T, 'add', '-A'); git(T, 'commit', '-q', '-m', 'seed');
    git(T, 'branch', '-q', '-M', 'main'); git(T, 'remote', 'add', 'origin', bare);
    git(T, 'checkout', '-q', '-b', 'review/EP-demo/stories-S01');
    process.exitCode = 0;
    // pass --platform so open-pr's OWN platform detection passes (a bare-file remote is neither
    // github nor gitlab) and execution actually reaches the product-shape delegation, not the early abort.
    let res;
    const out = await grab(() => runOpenPr(T, { platform: 'github' }).then((r) => { res = r; }));
    assert.match(out, /no Product platform/);                 // proves the delegated gateOpen was reached
    assert.doesNotMatch(out, /could not detect platform/); // ...not the early platform-detection abort
    assert.ok(!res?.url, 'no PR opened');
    assert.ok(process.exitCode, 'delegated no-PR result sets a non-zero exit code (P2 line)');
  } finally {
    // restore global state + temp dirs even if an assertion throws, so a failure here cannot leak a
    // non-zero exit code to the runner or strand temp repos (CodeRabbit).
    process.exitCode = prev;
    fs.rmSync(T, { recursive: true, force: true });
    if (bare) fs.rmSync(bare, { recursive: true, force: true });
  }
});

// A standalone code repo on a task branch, pushable to a bare remote — so runOpenPr reaches the
// create step and the base it hands the platform can actually be asserted.
function codeRepoWithRemote() {
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-base-'));
  const bare = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-basebare-'));
  git(bare, 'init', '-q', '--bare');
  git(T, 'init', '-q'); git(T, 'config', 'user.email', 'a@b.c'); git(T, 'config', 'user.name', 'x');
  fs.writeFileSync(path.join(T, 'seed.txt'), '0'); git(T, 'add', '-A'); git(T, 'commit', '-q', '-m', 'feat: seed');
  git(T, 'branch', '-q', '-M', 'staging'); git(T, 'remote', 'add', 'origin', bare);
  git(T, 'checkout', '-q', '-b', 'feat/EP-demo-S01-T01-x');
  return { T, bare };
}

test('runOpenPr bases the PR on the platform default, not a hardcoded main (#168)', async () => {
  const prev = process.exitCode;
  const { T, bare } = codeRepoWithRemote();
  try {
    process.exitCode = 0;
    let seen;
    const creator = (_p, o) => { seen = o; return { ok: true, url: 'https://x/pull/1' }; };
    // no repos registry here — this is the "run it from inside the code repo" path, where `meta` is
    // null and the old code fell straight through to 'main'.
    const runner = fakeRunner({ 'gh repo view': 'staging' });
    const out = await grab(() => runOpenPr(T, { platform: 'github', creator, runner }));
    assert.equal(seen.base, 'staging', 'the PR targets the repo default, not main');
    assert.match(out, /base staging/);
    assert.doesNotMatch(out, /not the repo default/, 'no warning when the base IS the default');
    assert.ok(!process.exitCode);
  } finally {
    process.exitCode = prev;
    fs.rmSync(T, { recursive: true, force: true });
    fs.rmSync(bare, { recursive: true, force: true });
  }
});

test('runOpenPr never lets the Product default_branch become a code repo\'s base (#168)', async () => {
  const prev = process.exitCode;
  const { T, bare } = codeRepoWithRemote();
  // A Product that owns this repo via the registry. The Product's own trunk is `trunk` — a DIFFERENT repo's
  // branch, which must never leak into a code-repo PR — and the registry entry deliberately declares
  // no default_branch, so the resolution has to fall past the Product rung to the platform.
  const H = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-baseproduct-'));
  try {
    process.exitCode = 0;
    fs.mkdirSync(path.join(H, '.sdlc'), { recursive: true });
    fs.writeFileSync(path.join(H, '.sdlc/hub.json'), JSON.stringify({ platform: 'github', default_branch: 'trunk', roster: [] }));
    fs.writeFileSync(path.join(H, '.sdlc/repos.json'), JSON.stringify({ repos: [{ name: 'backend', path: T, platform: 'github' }] }));
    let seen;
    const creator = (_p, o) => { seen = o; return { ok: true, url: 'https://x/pull/1' }; };
    const runner = fakeRunner({ 'gh repo view': 'staging' });
    await grab(() => runOpenPr(H, { repo: 'backend', creator, runner }));
    assert.equal(seen.base, 'staging', 'the code repo\'s own default wins');
    assert.notEqual(seen.base, 'trunk', 'the Product trunk never leaks into a connected repo\'s PR');
  } finally {
    process.exitCode = prev;
    fs.rmSync(T, { recursive: true, force: true });
    fs.rmSync(bare, { recursive: true, force: true });
    fs.rmSync(H, { recursive: true, force: true });
  }
});

test('runOpenPr refuses to open when HEAD is the resolved base, not just when it is main (#168)', async () => {
  const prev = process.exitCode;
  const { T, bare } = codeRepoWithRemote();
  try {
    process.exitCode = 0;
    git(T, 'checkout', '-q', 'staging');   // the repo's real trunk — never `main` here
    let called = false;
    const creator = () => { called = true; return { ok: true, url: 'https://x/pull/1' }; };
    const runner = fakeRunner({ 'gh repo view': 'staging' });
    const out = await grab(() => runOpenPr(T, { platform: 'github', creator, runner }));
    assert.match(out, /on staging — switch to your task branch first/);
    assert.ok(!called, 'no PR is opened from the base branch');
    assert.ok(process.exitCode, 'the guard sets a non-zero exit code');
  } finally {
    process.exitCode = prev;
    fs.rmSync(T, { recursive: true, force: true });
    fs.rmSync(bare, { recursive: true, force: true });
  }
});

test('runOpenPr warns (but still opens) when the base is not the platform default (#168)', async () => {
  const prev = process.exitCode;
  const { T, bare } = codeRepoWithRemote();
  try {
    process.exitCode = 0;
    let seen;
    const creator = (_p, o) => { seen = o; return { ok: true, url: 'https://x/pull/1' }; };
    const runner = fakeRunner({ 'gh repo view': 'staging' });
    const out = await grab(() => runOpenPr(T, { platform: 'github', base: 'release/1.0', creator, runner }));
    assert.equal(seen.base, 'release/1.0', '--base is still honoured — the warning never blocks');
    assert.match(out, /not the repo default 'staging'/);
    assert.match(out, /CodeRabbit/);
    assert.match(out, /opened https:\/\/x\/pull\/1/);
    assert.ok(!process.exitCode);
  } finally {
    process.exitCode = prev;
    fs.rmSync(T, { recursive: true, force: true });
    fs.rmSync(bare, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------------------------
// Gate predicate — pure, the heart of the gate
// ---------------------------------------------------------------------------------------------
// `stateInvariants` is pulled in HERE, not with the epic-state block further down: top-level `await
// import` yields, and node:test may already be running the gate tests that assert on it by then.
const { gatePredicate, artifactHash, nextAction, preconditionsMet, stateInvariants } = await import('./epic-state.mjs');

const baseStep = { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', risk_tags: [] };
const escStep = { id: 'architecture-review', type: 'review+approve', artifact: 'architecture.md', risk_tags: ['contract'] };
const appr = (over) => ({ step: 'epic-review', status: 'approved', artifactHash: 'sha256:H1', ...over });

test('gatePredicate: a team gate needs one approver, whoever they are, then merged + resolved (E62)', () => {
  const none = gatePredicate({ step: baseStep, approvals: [], currentHash: 'sha256:H1', merged: true, threadsResolved: true });
  assert.equal(none.passed, false);
  assert.deepEqual(none.missing, ['1 approval(s)']);
  // No role anywhere: the roster that gave one is gone, and the gate counts people.
  const p = gatePredicate({ step: baseStep, approvals: [appr({ approver: 'al' })], currentHash: 'sha256:H1', merged: true, threadsResolved: true });
  assert.equal(p.passed, true);
  assert.equal(p.rule, 'count');
  // An approval an older release recorded still carries a role. It counts as the person, not the role.
  const old = gatePredicate({ step: baseStep, approvals: [appr({ approver: 'bob', role: 'reviewer' })], currentHash: 'sha256:H1', merged: true, threadsResolved: true });
  assert.equal(old.passed, true, 'a reviewer with no owner beside them passes now — the owner rule is gone');
});

test('gatePredicate: unresolved comments hold the gate in-review', () => {
  const approvals = [appr({ approver: 'alice', role: 'owner' }), appr({ approver: 'bob', role: 'reviewer' })];
  const p = gatePredicate({ step: baseStep, approvals, currentHash: 'sha256:H1', merged: true, threadsResolved: false });
  assert.equal(p.passed, false);
  assert.ok(p.missing.includes('unresolved review comments'));
});

test('gatePredicate: an approval against a stale hash is revoked', () => {
  const approvals = [appr({ approver: 'alice', role: 'owner' }), appr({ approver: 'bob', role: 'reviewer' })];
  const p = gatePredicate({ step: baseStep, approvals, currentHash: 'sha256:H2', merged: true, threadsResolved: true });
  assert.equal(p.passed, false);
  assert.equal(p.staleDropped, 2);
  assert.ok(p.missing.some((m) => /revoked/.test(m)));
});

test('gatePredicate: a contract step holds on the base alone — the risk step is reported, not enforced until E108 (E62)', () => {
  // Until E108 (the capped count plus `yad gate lower --reason`), a contract gate asking for three would lock out a two-person team. So one
  // approver passes it, and the two it is short are said out loud rather than enforced.
  const one = [{ step: 'architecture-review', status: 'approved', approver: 'al', artifactHash: 'sha256:C' }];
  const p = gatePredicate({ step: escStep, approvals: one, currentHash: 'sha256:C', merged: true });
  assert.equal(p.passed, true);
  assert.equal(p.rule, 'count');
  assert.equal(p.gateRule.needed, 3);
  assert.equal(p.short, 2);
  assert.deepEqual(p.missing, []);
  const none = gatePredicate({ step: escStep, approvals: [], currentHash: 'sha256:C', merged: true });
  assert.equal(none.passed, false);
  assert.deepEqual(none.missing, ['1 approval(s)'], 'the missing line asks for the base, not the full count');
});

test('gatePredicate: a record naming nobody is nobody — it cannot pass a team gate on its own (E62 review)', () => {
  for (const approvals of [[appr({})], [appr({ approver: '' })], [appr({ approver: '   ' })]]) {
    const p = gatePredicate({ step: baseStep, approvals, currentHash: 'sha256:H1', merged: true, threadsResolved: true });
    assert.equal(p.passed, false, JSON.stringify(approvals));
    assert.equal(p.have, 0);
  }
});

test('gatePredicate: solo waives approvals — merged + resolved passes with zero approvals', () => {
  const p = gatePredicate({ step: baseStep, approvals: [], currentHash: 'sha256:H1', merged: true, threadsResolved: true, solo: true });
  assert.equal(p.passed, true);
  assert.equal(p.rule, 'solo');
});

test('gatePredicate: solo still requires the merge and resolved threads', () => {
  const unmerged = gatePredicate({ step: baseStep, approvals: [], merged: false, threadsResolved: true, solo: true });
  assert.equal(unmerged.passed, false);
  assert.ok(unmerged.missing.includes('review PR/MR not merged'));
  const unresolved = gatePredicate({ step: baseStep, approvals: [], merged: true, threadsResolved: false, solo: true });
  assert.equal(unresolved.passed, false);
  assert.ok(unresolved.missing.includes('unresolved review comments'));
});

test('gatePredicate: requireEngagement counts only verified approvals (soft default counts both)', () => {
  const approvals = [appr({ approver: 'bob', engagement: 'none' })];
  // soft (default): the bare approval still counts → passes.
  assert.equal(gatePredicate({ step: baseStep, approvals, currentHash: 'sha256:H1', merged: true, threadsResolved: true }).passed, true);
  // strict: bob's unengaged approval does not count → the one approver is missing.
  const strict = gatePredicate({ step: baseStep, approvals, currentHash: 'sha256:H1', merged: true, threadsResolved: true, requireEngagement: true });
  assert.equal(strict.passed, false);
  assert.ok(strict.missing.includes('1 approval(s)'));
  assert.ok(strict.missing.some((m) => /verified engagement/.test(m)));
  // once bob's approval is engagement-verified, strict passes.
  const ok = gatePredicate({
    step: baseStep, currentHash: 'sha256:H1', merged: true, threadsResolved: true, requireEngagement: true,
    approvals: [appr({ approver: 'bob', engagement: 'verified' })],
  });
  assert.equal(ok.passed, true);
});

test('gatePredicate: solo passes an escalated step with no approvals at all', () => {
  const p = gatePredicate({ step: escStep, approvals: [], currentHash: 'sha256:C', merged: true, threadsResolved: true, solo: true });
  assert.equal(p.passed, true);
  assert.equal(p.rule, 'solo');
});

test('gatePredicate: discovery-review is an ordinary count gate (one approver, no risk step)', () => {
  const step = { id: 'discovery-review', type: 'review+approve', artifact: 'discovery/', risk_tags: [] };
  const approvals = [{ step: 'discovery-review', status: 'approved', approver: 'al', artifactHash: 'sha256:D' }];
  const p = gatePredicate({ step, approvals, currentHash: 'sha256:D', merged: true, threadsResolved: true });
  assert.equal(p.passed, true);
  assert.equal(p.rule, 'count');
  assert.equal(p.gateRule.needed, 1);
});

test('gatePredicate: a SKIPPED step short-circuits — passes with zero approvals (rule: skipped)', () => {
  const step = { id: 'ui-design-review', type: 'review+approve', artifact: 'ui-design.md', risk_tags: [], skipped: true, skipReason: 'no UI', status: 'done' };
  const p = gatePredicate({ step, approvals: [], merged: false, threadsResolved: false, optional: ['ui-design'] });
  assert.equal(p.passed, true, 'a skipped step is satisfied regardless of merge/threads/approvals');
  assert.equal(p.rule, 'skipped');
  assert.deepEqual(p.missing, []);

  // FAIL CLOSED. The flag is honoured only for a step THIS epic's route marks optional, and the gate
  // is told which those are. A caller that passes none — or an epic on a route where this step is
  // required — falls through to the real predicate rather than passing on the flag alone.
  for (const optional of [undefined, [], ['analysis']]) {
    const q = gatePredicate({ step, approvals: [], merged: false, threadsResolved: false, optional });
    assert.equal(q.passed, false, `a skip was honoured with optional=${JSON.stringify(optional)}`);
    assert.notEqual(q.rule, 'skipped');
  }
});

// ---------------------------------------------------------------------------------------------
// The per-step gate rule (E7) — `needed = base + risk step`, counted in PEOPLE
// ---------------------------------------------------------------------------------------------
// The count is REPORTED, not enforced: the base (E62) is the only thing that decides `passed`. E72
// computes the capacity cap and reports it; E108 enforces the capped count beside its escape hatch, and
// enforcing any of it sooner would make a small team's contract gate unpassable. So these tests pin what the count SAYS — `gateRule`, `have`, `short` — and pin that
// it changes no verdict. The case they are built around is the one the role rule cannot see: one person
// holding two roles is two roles and one approver.
const { gateRuleFor, gateRuleSum } = await import('./epic-state.mjs');

test('gateRuleFor: the risk step is contract +2, auth/payments +1, nothing +0', () => {
  assert.deepEqual(gateRuleFor({ id: 'epic-review', risk_tags: [] }), { base: 1, riskStep: 0, needed: 1, risk: 'normal' });
  assert.deepEqual(gateRuleFor({ id: 'architecture-review', risk_tags: ['contract'] }), { base: 1, riskStep: 2, needed: 3, risk: 'contract' });
  assert.deepEqual(gateRuleFor({ id: 'epic-review', risk_tags: ['auth'] }), { base: 1, riskStep: 1, needed: 2, risk: 'high' });
  assert.deepEqual(gateRuleFor({ id: 'epic-review', risk_tags: ['payments'] }), { base: 1, riskStep: 1, needed: 2, risk: 'high' });
});

test('gateRuleFor: the tier NAME comes from the winning tag, not from the number', () => {
  // If `auth` ever moves to +2, an auth-only step must not start printing "contract risk 2".
  assert.equal(gateRuleFor({ risk_tags: ['auth'] }).risk, 'high');
  assert.equal(gateRuleFor({ risk_tags: ['auth', 'contract'] }).risk, 'contract');
  assert.equal(gateRuleFor({ risk_tags: ['contract', 'auth'] }).risk, 'contract', 'tag order does not decide the tier');
});

test('gateRuleFor: a hand-edited risk_tags of the wrong TYPE is read as no tags, not a crash', () => {
  // `risk_tags: "contract"` (a string where the shape says array) is a plausible hand edit, and the gate
  // that was about to report on the step must still report.
  assert.deepEqual(gateRuleFor({ risk_tags: 'contract' }), { base: 1, riskStep: 0, needed: 1, risk: 'normal' });
  assert.deepEqual(gateRuleFor({ risk_tags: { contract: true } }), { base: 1, riskStep: 0, needed: 1, risk: 'normal' });
});

test('gateRuleFor: several tags take the MAXIMUM step, never the sum', () => {
  // A gate is one decision about the riskiest thing it touches. Summing would ask a three-tag step for
  // five approvals, which no small team can produce and no roadmap rule asks for.
  assert.equal(gateRuleFor({ id: 'x', risk_tags: ['contract', 'auth', 'payments'] }).needed, 3);
  assert.equal(gateRuleFor({ id: 'x', risk_tags: ['auth', 'payments'] }).needed, 2);
});

test('gateRuleFor: an unknown tag adds nothing, and a step with no tags at all is safe', () => {
  // A project may hold a step from a newer yadflow carrying a tag this version has never heard of
  // (change-safety rule 3 — the file wins). It must not crash and must not silently escalate.
  assert.equal(gateRuleFor({ id: 'x', risk_tags: ['quantum'] }).needed, 1);
  assert.equal(gateRuleFor({ id: 'x', risk_tags: ['quantum', 'contract'] }).needed, 3);
  assert.equal(gateRuleFor({}).needed, 1);
  assert.equal(gateRuleFor(null).needed, 1);
});

test('gateRuleSum: one sentence of arithmetic, shared by every surface that prints it', () => {
  // Three surfaces print this sum (`gate sync`, `gate status`, the review-PR body), each wrapping it in
  // its own sentence. Pinned here because three hand-built copies of the same arithmetic would eventually
  // disagree. The predicate does NOT print it — the count never enters `missing` (see the test below).
  assert.equal(gateRuleSum(gateRuleFor({ risk_tags: [] })), '1 approver = base 1');
  assert.equal(gateRuleSum(gateRuleFor({ risk_tags: ['auth'] })), '2 approvers = base 1 + high risk 1');
  assert.equal(gateRuleSum(gateRuleFor({ risk_tags: ['contract'] })), '3 approvers = base 1 + contract risk 2');
});

test('gatePredicate: the count counts people, not records, and its risk step holds nothing', () => {
  // Three records an older release wrote, from two people: alice once per role the roster gave her.
  // The count asks a contract step for three. THIS is the case that keeps the risk step advisory: a
  // two-person team would be deadlocked by an uncapped count, with no escape until E108.
  const approvals = [
    { step: 'architecture-review', status: 'approved', approver: 'alice', role: 'owner', artifactHash: 'sha256:C' },
    { step: 'architecture-review', status: 'approved', approver: 'alice', role: 'reviewer', artifactHash: 'sha256:C' },
    { step: 'architecture-review', status: 'approved', approver: 'carol', role: 'domain-owner', domain: 'backend', artifactHash: 'sha256:C' },
  ];
  const p = gatePredicate({ step: escStep, approvals, currentHash: 'sha256:C', merged: true, threadsResolved: true });
  assert.equal(p.passed, true, 'the base decides the gate, and it is satisfied');
  assert.equal(p.have, 2, 'two distinct people, though three approval records');
  assert.equal(p.gateRule.needed, 3);
  assert.equal(p.short, 1, 'the shortfall is reported, never enforced here');
  assert.deepEqual(p.missing, [], 'nothing the risk step says may hold a gate before E108');

  // A third human clears the shortfall.
  approvals.push({ step: 'architecture-review', status: 'approved', approver: 'dave', artifactHash: 'sha256:C' });
  const full = gatePredicate({ step: escStep, approvals, currentHash: 'sha256:C', merged: true, threadsResolved: true });
  assert.equal(full.have, 3);
  assert.equal(full.short, 0);
});

test('gatePredicate: a hand-added risk tag raises what the count asks of an ordinary step', () => {
  // The tags are read from the EPIC's recorded step, not from the catalogue — a team that marks
  // `epic-review` as touching auth has raised what the count asks for, and the engine honours the file.
  const step = { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', risk_tags: ['auth'] };
  const onePerson = [appr({ approver: 'alice', role: 'owner' }), appr({ approver: 'alice', role: 'reviewer' })];
  const tagged = gatePredicate({ step, approvals: onePerson, currentHash: 'sha256:H1', merged: true, threadsResolved: true });
  assert.equal(tagged.gateRule.needed, 2);
  assert.equal(tagged.gateRule.risk, 'high');
  assert.equal(tagged.have, 1);
  assert.equal(tagged.short, 1);
  // The same approvals on the same step WITHOUT the tag are not short: the tag is what moved the number.
  const untagged = gatePredicate({ step: baseStep, approvals: onePerson, currentHash: 'sha256:H1', merged: true, threadsResolved: true });
  assert.equal(untagged.gateRule.needed, 1);
  assert.equal(untagged.short, 0);
  // Neither verdict moved — the base decides both, and one person meets it.
  assert.equal(tagged.passed, true);
  assert.equal(untagged.passed, true);
});

test('gatePredicate: solo reports no shortfall, and still says what team mode would ask', () => {
  const p = gatePredicate({ step: escStep, approvals: [], currentHash: 'sha256:C', merged: true, threadsResolved: true, solo: true });
  assert.equal(p.passed, true);
  assert.equal(p.gateRule.needed, 3, 'the rule is a fact about the step, reported even where approvals are waived');
  assert.equal(p.have, 0);
  assert.equal(p.short, 0, 'a waived gate is not "short" of anything');
});

test('gatePredicate: a waived path reports `have: null`, which is not the same as zero approvals', () => {
  // Nothing is counted on an inherited or skipped step: the approvals live upstream in the thread, or
  // there was no review at all. Reporting 0 would claim the step was counted and came up empty.
  const inherited = { id: 'architecture-review', type: 'review+approve', artifact: 'architecture.md', risk_tags: ['contract'], inherited: true, inheritedFrom: 'EP-parent', boundHash: null };
  const i = gatePredicate({ step: inherited, approvals: [], currentHash: 'sha256:C' });
  assert.equal(i.passed, true);
  assert.equal(i.have, null);
  assert.equal(i.short, 0);
  assert.equal(i.gateRule.needed, 3);

  const skipped = { id: 'ui-design-review', type: 'review+approve', artifact: 'ui-design.md', risk_tags: [], skipped: true, status: 'done' };
  const k = gatePredicate({ step: skipped, approvals: [], merged: false, threadsResolved: false, optional: ['ui-design'] });
  assert.equal(k.have, null);
  assert.equal(k.gateRule.needed, 1);
});

test('gatePredicate: an engagement-gated approval does not count as an approver either', () => {
  // requireEngagement filters the approvals BEFORE anything counts them, so a bare click cannot make
  // up the head count.
  const step = { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', risk_tags: ['payments'] };
  const approvals = [
    appr({ approver: 'alice', engagement: 'verified' }),
    appr({ approver: 'bob', engagement: 'none' }),
  ];
  const strict = gatePredicate({ step, approvals, currentHash: 'sha256:H1', merged: true, threadsResolved: true, requireEngagement: true });
  assert.equal(strict.have, 1);
  assert.equal(strict.gateRule.needed, 2);
  assert.equal(strict.short, 1);
  // The base is met by alice alone, so the gate passes — and the risk step's shortfall is reported only.
  assert.equal(strict.passed, true);
  // Without alice, bob's bare approval cannot meet the base either.
  const bare = gatePredicate({ step, approvals: [approvals[1]], currentHash: 'sha256:H1', merged: true, threadsResolved: true, requireEngagement: true });
  assert.equal(bare.have, 0);
  assert.equal(bare.passed, false);
  assert.ok(bare.missing.includes('1 approval(s)'));
});

// ---------------------------------------------------------------------------------------------
// `yad next` — the driver: nextAction() + preconditionsMet() (both pure)
// ---------------------------------------------------------------------------------------------
// Build a single state-machine step record for the test chains below.
const S = (id, type, status, artifact, extra = {}) => ({ id, type, status, artifact, risk_tags: [], ...extra });
// A small Shape chain at an arbitrary point: epic, epic-review, architecture, architecture-review.
const chain = (overrides) => ({
  epicId: 'EP-x',
  currentStep: overrides.currentStep,
  steps: [
    S('epic', 'author', overrides.epic ?? 'done', 'epic.md'),
    S('epic-review', 'review+approve', overrides.epicReview ?? 'done', 'epic.md'),
    S('architecture', 'author', overrides.architecture ?? 'blocked', 'architecture.md'),
    S('architecture-review', 'review+approve', overrides.architectureReview ?? 'blocked', 'architecture.md'),
  ],
});

test('preconditionsMet: greenfield (no state) — epic is the entry step, architecture is not', () => {
  assert.equal(preconditionsMet(null, 'epic').ok, true);
  assert.equal(preconditionsMet(null, 'architecture').ok, false);
});

test('preconditionsMet: current step runnable, downstream blocked, done step not re-runnable', () => {
  const state = chain({ currentStep: 'architecture', architecture: 'in_progress' });
  assert.equal(preconditionsMet(state, 'architecture').ok, true);
  const blocked = preconditionsMet(state, 'architecture-review');
  assert.equal(blocked.ok, false);
  assert.equal(blocked.blockedBy, 'architecture');
  assert.equal(preconditionsMet(state, 'epic').ok, false); // already done
  assert.equal(preconditionsMet(state, 'nope').ok, false); // unknown
});

test('nextAction: author step → invoke the mapped skill', () => {
  const a = nextAction({ state: chain({ currentStep: 'architecture', architecture: 'in_progress' }), productPrs: [] }, { epic: 'EP-x' });
  assert.equal(a.kind, 'author');
  assert.equal(a.skill, 'yad-architecture');
  assert.equal(a.artifact, 'architecture.md');
});

test('nextAction: review step with no PR → open; with a PR → sync', () => {
  const state = chain({ currentStep: 'epic-review', epicReview: 'in_review', architecture: 'blocked' });
  const open = nextAction({ state, productPrs: [] }, { epic: 'EP-x' });
  assert.equal(open.kind, 'review-open');
  assert.equal(open.command, 'yad gate open EP-x epic.md');
  const sync = nextAction({ state, productPrs: [{ artifact: 'epic.md', number: 7 }] }, { epic: 'EP-x' });
  assert.equal(sync.kind, 'review-sync');
  assert.equal(sync.command, 'yad gate sync EP-x epic.md');
  assert.equal(sync.pr, 7);
});

test('nextAction: ready-for-build → build; an open test-cases track is surfaced as parallel', () => {
  const base = { epicId: 'EP-x', currentStep: 'ready-for-build', steps: [S('stories-review', 'review+approve', 'done', 'stories/')] };
  assert.equal(nextAction({ state: base, productPrs: [] }).kind, 'build');
  assert.equal(nextAction({ state: base, productPrs: [] }).parallel, null);
  const withTc = { ...base, steps: [...base.steps, S('test-cases', 'author', 'in_progress', 'test-cases.md')] };
  const a = nextAction({ state: withTc, productPrs: [] });
  assert.equal(a.kind, 'build');
  assert.equal(a.parallel.skill, 'yad-test-cases');
});

// --- Build: nextAction surfaces each story/repo's next sub-step from build-state ---
const { buildNextForRepo, buildNextActions } = await import('./epic-state.mjs');
// One repo's build-state at an arbitrary point: pass which steps are done + the active step.
const repoBS = (currentStep, done = [], extra = {}) => ({
  currentStep,
  steps: ['spec', 'tasks', 'implement', 'checks', 'engineer-review'].map((id) => ({
    id,
    automation: extra[id]?.automation || 'human_approve',
    locked: id === 'engineer-review',
    status: done.includes(id) ? 'done' : (id === currentStep ? (extra[id]?.status || 'in_progress') : 'blocked'),
  })),
});

test('a halted Build lane reports itself as blocked, and only while it carries the record that says so', () => {
  // `yad-run` marks a lane `blocked` when a check fails, a diff overruns its declared files, or it
  // touches the contract surface. That is the NEW meaning of the word, written by a skill into a file
  // the engine deliberately does not migrate — so the record is the only thing keeping it legible.
  const halted = repoBS('implement', ['spec', 'tasks'], {
    implement: { status: 'blocked' },
  });
  halted.steps.find((s) => s.id === 'implement').record = { reason: 'scope overrun: cli/gate.mjs', by: '@al', date: '2026-08-01' };
  const stuck = buildNextForRepo(halted);
  assert.equal(stuck.step, 'implement');
  assert.equal(stuck.status, 'blocked', 'a halted lane says so');
  assert.equal(stuck.shipped, false, 'and is certainly not shipped');

  // A lane halted by an OLDER yad-run carries no record, so it reads as `todo`. Nothing advances past
  // it either way — which is the whole reason not migrating this file is affordable — but the word is
  // lost until the next run rewrites it.
  const legacy = repoBS('implement', ['spec', 'tasks'], { implement: { status: 'blocked' } });
  assert.equal(buildNextForRepo(legacy).status, 'todo');
  assert.equal(buildNextForRepo(legacy).step, 'implement', 'and it is still the step the lane is on');

  // A word this release cannot name is reported as itself rather than renamed to something it is not.
  const odd = repoBS('checks', ['spec', 'tasks', 'implement'], { checks: { status: 'quarantined' } });
  assert.equal(buildNextForRepo(odd).status, 'quarantined');
});

