test('setupModeFields: both setup write sites record mode_set only when an existing Product changes mode (E10)', () => {
  assert.deepEqual(setupModeFields('/nowhere', {}, true, { today: '2026-09-15' }), { solo: true, mode: 'solo' }, 'a first run is not a switch');
  assert.deepEqual(setupModeFields('/nowhere', { solo: true, mode: 'solo' }, true), { solo: true, mode: 'solo' });
  const changed = setupModeFields('/nowhere', { solo: false, roster: [] }, true, { today: '2026-09-15' });
  assert.deepEqual([changed.solo, changed.mode, changed.mode_set.from, changed.mode_set.to, changed.mode_set.reason, changed.mode_set.date],
    [true, 'solo', 'team', 'solo', 'yad setup', '2026-09-15']);
});

test('selectIdeTargets: interactive input re-prompts, then trims and deduplicates valid targets', async () => {
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-ide-prompt-'));
  const answers = ['.cluade', ' .zencoder, .claude, .zencoder '];
  let calls = 0;
  const selected = await captureConsole(() => selectIdeTargets(T, undefined, async () => answers[calls++]));
  assert.equal(calls, 2, 'invalid interactive selection is asked again');
  assert.deepEqual(selected.value, ['.zencoder', '.claude']);
  assert.match(selected.out, /unsupported IDE target/);

  assert.deepEqual(
    await selectIdeTargets(T, [' .agents ', '.claude', '.agents']),
    ['.agents', '.claude'],
    'programmatic valid input is canonicalized',
  );
  await assert.rejects(
    selectIdeTargets(T, undefined, async () => undefined),
    /selection ended before a valid choice/,
    'EOF/cancel does not loop forever',
  );

  // A project with NO agent directory is the only one shown the default, and the default is Claude
  // Code plus the cross-agent directory — together they cover every agent the menu names (E11).
  let offered = null;
  let menu = null;
  await selectIdeTargets(T, undefined, async (prompt, def) => { menu = prompt; offered = def; return '.claude'; });
  assert.equal(offered, DEFAULT_IDE_TARGETS.join(','));
  // The menu names the AGENTS, not just the directories: `.agents` says nothing to a Codex user.
  assert.match(menu, /\.agents = .*Codex CLI/);
  assert.match(menu, /\.cursor = .*Cursor/);
  // An EXISTING INSTALL is offered back instead — detection beats the default, so nobody is talked
  // into a target they did not choose. It takes the install container, not a bare directory: plenty of
  // repos keep a `.cursor/` for rules alone and have never installed a skill in their lives.
  fs.mkdirSync(path.join(T, '.zencoder/skills'), { recursive: true });
  await selectIdeTargets(T, undefined, async (_p, def) => { offered = def; return '.zencoder'; });
  assert.equal(offered, '.zencoder');
  fs.rmSync(T, { recursive: true, force: true });
});

