// The re-open loop (issue #156): an already-approved architecture step is re-opened, the contract
// surface is edited + re-locked, a FRESH review PR is opened, the same reviewers approve it, and it is
// merged. In verified mode nothing ever moves the step back to `in_review` (CI is the sole ledger
// writer), so the merge-time sync used to hit a blanket "already done — skipping" and write only the
// PR pointer: the step read `done` with every approval bound to the pre-edit hash.
async function reopenAndReapprove(reviews) {
  const { T, ep } = scaffoldEpic();
  const first = { ok: true, state: 'MERGED', merged: true, headOid: 'abc', reviews, threads: [] };
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => first });
  const state0 = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  assert.equal(state0.steps.find((s) => s.id === 'architecture-review').status, 'done', 'first review advanced');

  // Widen the surface + re-lock: every prior approval is now bound to a stale hash.
  fs.writeFileSync(path.join(ep, 'contract.md'), '<!-- CONTRACT-SURFACE:BEGIN -->\nPOST /x\nPOST /y\n<!-- CONTRACT-SURFACE:END -->\n');
  const stale = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json')));
  const { artifactHash } = await import('./epic-state.mjs');
  const newHash = artifactHash(ep, 'architecture.md');
  assert.ok(stale.every((a) => a.artifactHash !== newHash), 'the re-lock revoked the prior approvals');

  // A NEW review MR/PR for the re-opened step, approved by the same reviewers, merged.
  writePrLedger(path.join(ep, '.sdlc'), JSON.stringify([
    { step: 'architecture-review', artifact: 'architecture.md', platform: 'github', number: 11, url: 'http://x/11', branch: 'review/EP-test/architecture', lastSyncedAt: null },
  ]));
  await gateSync(T, { epic: 'EP-test', today: '2026-06-20', reader: () => first });
  return { T, ep, newHash };
}

test('gate sync: a re-opened, re-approved review re-binds its approvals (issue #156)', async () => {
  const { T, ep, newHash } = await reopenAndReapprove(fullApproval.reviews);
  const after = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json')));
  const live = after.filter((a) => a.status === 'approved' && a.artifactHash === newHash);
  assert.ok(live.length >= 3, `the new approvals must bind to the re-locked surface, got ${JSON.stringify(after)}`);
  // The chain is NOT re-advanced: the step stays done and the next step keeps its own progress.
  const state = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  assert.equal(state.steps.find((s) => s.id === 'architecture-review').status, 'done');
  assert.equal(state.currentStep, 'ui-design');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate sync: a re-approval on a new PR re-binds even without review timestamps (GitLab)', async () => {
  // GitLab approvals carry no submittedAt at all, so "is this a newer review?" cannot be answered by
  // time. A different PR/MR number is the proof: a re-opened review is always a new MR.
  const noTimestamps = fullApproval.reviews.map(({ login, state }) => ({ login, state }));
  const { T, ep, newHash } = await reopenAndReapprove(noTimestamps);
  const after = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json')));
  const live = after.filter((a) => a.status === 'approved' && a.artifactHash === newHash);
  assert.ok(live.length >= 3, `a timestampless re-approval on MR #11 must re-bind, got ${JSON.stringify(after)}`);
  assert.ok(after.every((a) => a.pr === 11), 'each approval records the PR/MR it arrived on');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate sync: a done step never loses the approvals that passed it', async () => {
  const { T, ep } = scaffoldEpic();
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => fullApproval });
  const before = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json')));
  assert.ok(before.length >= 3, 'the gate passed on real approvals');

  // A later read that returns cleanly but maps NO approvers — an ordinary roster edit (a login
  // changed or a member left), a GitLab approval reset, or a degraded-but-ok read. On an OPEN step
  // this correctly drops them; on a step that already advanced it would erase the record of WHY it
  // advanced, leaving `done` with zero approvals.
  await gateSync(T, { epic: 'EP-test', today: '2026-06-20', reader: () => ({ ...fullApproval, reviews: [] }) });
  const after = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json')));
  assert.deepEqual(after, before, 'a closed gate keeps its approval record when the platform reports none');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate sync: an OPEN step still drops an approval the platform no longer reports', async () => {
  const { T, ep } = scaffoldEpic();
  // Not merged → the step stays in_review, so the platform remains the live source of truth.
  const held = { ...fullApproval, merged: false };
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => held });
  assert.ok(JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json'))).length >= 3);
  await gateSync(T, { epic: 'EP-test', today: '2026-06-10', reader: () => ({ ...held, reviews: [] }) });
  assert.deepEqual(JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/approvals.json'))), [], 'a dismissal on an open step still vanishes');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate sync: re-syncing a done step is a byte-identical no-op, threads and all', async () => {
  const { T, ep } = scaffoldEpic();
  // A merged review that still carries ONE unresolved thread — the ordinary case, and the one that
  // churns: `recordComments` allocates a fresh round per call, so an unguarded re-sync appends a
  // record set (and therefore a default-branch gate commit) on every pass of the 15-minute sweep.
  const merged1thread = {
    ...fullApproval,
    threads: [{ id: 't', resolved: false, login: 'x', body: 'a nit nobody resolved' }],
  };
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => fullApproval });
  const snapshot = () => ({
    approvals: fs.readFileSync(path.join(ep, '.sdlc/approvals.json'), 'utf8'),
    comments: fs.readFileSync(path.join(ep, '.sdlc/comments.json'), 'utf8'),
    productPrs: fs.readFileSync(path.join(ep, '.sdlc/hub-prs.json'), 'utf8'),
    reviews: fs.readdirSync(path.join(ep, 'reviews')).sort(),
  });
  // Baseline BEFORE any re-sync, so a write by the first re-sync cannot be baked into it.
  const before = snapshot();
  for (const day of ['2026-06-20', '2026-06-21', '2026-06-22']) {
    await gateSync(T, { epic: 'EP-test', today: day, reader: () => merged1thread });
  }
  assert.deepEqual(snapshot(), before, 'a re-sync of an already-done step must write nothing new');
  fs.rmSync(T, { recursive: true, force: true });
});

// `advanceState` opens the step FOLLOWING the one it closes, so a sync that passes two gates in the
// wrong order rewinds the epic: close architecture-review first (next: ui-design), then epic-review
// (next: architecture), and the already-done `architecture` author step reopens while currentStep
// points backward — the YAD-STATE-005 inconsistency `yad gate repair` exists to undo. gateSync used to
// rely on hub-prs.json happening to be in insertion order; once the file is written sorted by artifact
// that accident is gone, so the sync orders its targets by the chain explicitly.
test('gate sync: advances multiple passing gates in CHAIN order, never in ledger order', async () => {
  const { T, ep } = scaffoldEpic();
  const state = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  state.currentStep = 'epic-review';
  state.steps.unshift(
    { id: 'epic', type: 'author', artifact: 'epic.md', status: 'done', risk_tags: [] },
    { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', status: 'in_review', risk_tags: [] },
  );
  fs.writeFileSync(path.join(ep, '.sdlc/state.json'), JSON.stringify(state));
  // Ledger order is alphabetical (what canonicalProductPrs writes) — the REVERSE of the chain here.
  writePrLedger(path.join(ep, '.sdlc'), JSON.stringify([
    { step: 'architecture-review', artifact: 'architecture.md', platform: 'github', number: 7, url: null, branch: 'review/EP-test/architecture', lastSyncedAt: null },
    { step: 'epic-review', artifact: 'epic.md', platform: 'github', number: 8, url: null, branch: 'review/EP-test/epic', lastSyncedAt: null },
  ]));
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => fullApproval });
  const after = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  const status = (id) => after.steps.find((s) => s.id === id).status;
  assert.equal(status('epic-review'), 'done');
  assert.equal(status('architecture-review'), 'done');
  assert.equal(status('architecture'), 'done', 'the later gate must not reopen an author step the earlier one already closed');
  assert.equal(after.currentStep, 'ui-design', 'currentStep lands on the furthest step, not the earlier gate\'s successor');
  fs.rmSync(T, { recursive: true, force: true });
});

// issue #163. The test above passes on the BUGGY code because its ledger holds one step's approvals,
// which the drop-and-re-append upsert puts back exactly where they were. With TWO steps in the epic —
// the ordinary case — syncing step A moves A's records to the tail, syncing B moves B's past them, and
// the wired sweep (one `gate ci --branch <ref> --merged` per merged PR/MR) walks that rotation on every
// pass: each hop is a non-empty diff, so each hop commits and pushes, forever, with zero semantic
// change. This is the fixture that catches it.
test('gate sync: a two-step ledger is order-stable under a rotating re-sync (issue #163)', async () => {
  const { T, ep } = scaffoldEpic();
  const state = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  state.currentStep = 'epic-review';
  state.steps.unshift(
    { id: 'epic', type: 'author', artifact: 'epic.md', status: 'done', risk_tags: [] },
    { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', status: 'in_review', risk_tags: [] },
  );
  fs.writeFileSync(path.join(ep, '.sdlc/state.json'), JSON.stringify(state));
  const productPrs = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/hub-prs.json')));
  productPrs.push({ step: 'epic-review', artifact: 'epic.md', platform: 'github', number: 8, url: 'http://x/8', branch: 'review/EP-test/epic', lastSyncedAt: null });
  writePrLedger(path.join(ep, '.sdlc'), JSON.stringify(productPrs));

  const sync = (artifact, today) => gateSync(T, { epic: 'EP-test', artifact, today, reader: () => fullApproval });
  // Advance both gates, then let one full sweep settle the ledger.
  await sync('epic.md', '2026-06-09');
  await sync('architecture.md', '2026-06-09');
  const snapshot = () => ['approvals', 'comments', 'hub-prs'].map(
    (f) => fs.readFileSync(path.join(ep, '.sdlc', `${f}.json`), 'utf8'),
  );
  const before = snapshot();
  const approvals = JSON.parse(before[0]);
  assert.ok(
    new Set(approvals.map((a) => a.step)).size === 2,
    'the fixture really does hold two steps of approvals — otherwise this test proves nothing',
  );
  // Now walk the rotation the sweep walks, twice round. Every one of these used to be a commit.
  for (const day of ['2026-06-20', '2026-06-21']) {
    await sync('epic.md', day);
    assert.deepEqual(snapshot(), before, 'syncing epic.md must not reorder architecture-review\'s records');
    await sync('architecture.md', day);
    assert.deepEqual(snapshot(), before, 'syncing architecture.md must not reorder epic-review\'s records');
  }
  fs.rmSync(T, { recursive: true, force: true });
});

// The other half of #163's commit loop, reachable from the state the `alreadyDone` guard cannot cover.
// A review merged while one thread is still unresolved never passes the predicate, so its step stays
// `in_review` forever — `alreadyDone` is false on every pass, and `recordComments` used to allocate
// round = max+1 each time, appending a fresh record set (and a default-branch commit) every 15 minutes
// for the whole 7-day sweep window. A round is a change in thread state, not a sync.
test('gate sync: a merged-but-held review does not open a new comment round per sweep (issue #163)', async () => {
  const { T, ep } = scaffoldEpic();
  const stuck = {
    ...fullApproval,
    threads: [{ id: 't', resolved: false, login: 'bo', body: 'a nit nobody resolved' }],
  };
  const commentsFile = path.join(ep, '.sdlc/comments.json');
  const rounds = () => JSON.parse(fs.readFileSync(commentsFile, 'utf8')).filter((cm) => cm.step === 'architecture-review');

  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => stuck });
  const state = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/state.json')));
  assert.equal(state.steps.find((s) => s.id === 'architecture-review').status, 'in_review', 'the unresolved thread holds the gate — the step never goes done');
  assert.deepEqual([...new Set(rounds().map((cm) => cm.round))], [1], 'the first sync opens round 1');
  const before = fs.readFileSync(commentsFile, 'utf8');

  // The sweep keeps re-reading the same unchanged MR for a week.
  for (const day of ['2026-06-20', '2026-06-21', '2026-06-22']) {
    await gateSync(T, { epic: 'EP-test', today: day, reader: () => stuck });
  }
  assert.equal(fs.readFileSync(commentsFile, 'utf8'), before, 'an unchanged thread state re-records the same round, byte for byte');
  // Nor a new dated side file or sync date per day (issue #362): the same threads and approvals under
  // a new day's name were a daily commit with nothing new in them.
  const reviews = fs.readdirSync(path.join(ep, 'reviews')).sort();
  assert.ok(!reviews.some((f) => /2026-06-2[012]/.test(f)), `no dated review files for unchanged re-reads: ${reviews.join(', ')}`);
  const ptr = JSON.parse(fs.readFileSync(path.join(ep, '.sdlc/product-prs.json'), 'utf8')).find((p) => p.artifact === 'architecture.md');
  assert.equal(ptr.lastSyncedAt, '2026-06-09', 'the sync date stays on the day something last changed');

  // A genuinely new comment IS a new round — the idempotency must not swallow real activity.
  const escalated = { ...stuck, threads: [...stuck.threads, { id: 't2', resolved: false, login: 'ca', body: 'a second reviewer weighs in' }] };
  await gateSync(T, { epic: 'EP-test', today: '2026-06-23', reader: () => escalated });
  assert.deepEqual([...new Set(rounds().map((cm) => cm.round))].sort(), [1, 2], 'a changed thread state opens round 2');
  assert.ok(fs.existsSync(path.join(ep, 'reviews/architecture--2026-06-23--comments.md')), 'a real change still writes its dated side file');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate sync: a done step never posts engagement nudges on its merged PR', async () => {
  const { T } = scaffoldEpic();
  const posted = [];
  const poster = (_p, n, body) => { posted.push([n, body]); return { ok: true }; };
  // The nudge is a PLATFORM write. Re-running it on a closed review would @-mention reviewers on an
  // already-merged PR every time the sweep comes round. Bare approvals (no engagement marker) are
  // exactly what triggers it. The step is NOT merged on the first pass, so the nudges land while the
  // review is genuinely open.
  const bare = { ...fullApproval, merged: false, reviews: fullApproval.reviews.map(({ login, state }) => ({ login, state })) };
  await gateSync(T, { epic: 'EP-test', today: '2026-06-09', reader: () => bare, poster });
  assert.ok(posted.length > 0, 'an open review does nudge bare approvals');
  await gateSync(T, { epic: 'EP-test', today: '2026-06-10', reader: () => ({ ...bare, merged: true }), poster });
  const afterMerge = posted.length;
  // Now the step is done; every later sweep pass must stay silent on the platform.
  await gateSync(T, { epic: 'EP-test', today: '2026-06-20', reader: () => ({ ...bare, merged: true }), poster });
  assert.equal(posted.length, afterMerge, 'no further platform writes once the step is done');
  fs.rmSync(T, { recursive: true, force: true });
});


// Under the verified ledger the ledger records the PR pointer only at merge, so a review a human must push
