  const comments = [null, { step: 'x', commenter: '', role: 'reviewer', round: 1 }];
  const r = stampLegacyLogins({ approvals, comments }, { aliases: new Map([['alice', 'al'], ['', 'z']]), acceptedFor: () => { throw new Error('must not be asked'); } });
