test('E64 simulation: GitLab, two people a renamed roster gives one name, synced the same day — the stamp does not merge them, and the gate fails closed', async () => {
  // Every pre-E64 GitLab record holds the sync DATE, so x's and y's records under `sam` looked like one
  // review. Merged into one x record, y's approval of old content was bound to today's and passed the gate.
  const { stampLegacyLogins } = await import('./gate.mjs');
  const older = [legacyAppr('sam', 'owner', 'sha256:old'), legacyAppr('sam', 'reviewer', 'sha256:old')];
  const st = stampLegacyLogins({ approvals: older.map((a) => ({ ...a })) }, { aliases: new Map([['sam', 'x']]) });
  assert.deepEqual([st.stamped, st.unplaced, st.approvals], [0, 2, older]);
  const r = await legacySync({ roster: null, approvals: st.approvals, reviews: [{ login: 'x', state: 'APPROVED' }, { login: 'y', state: 'APPROVED' }], merged: true });
  try {
    const recs = r.read();
    assert.ok(!recs.some((a) => a.artifactHash === r.cur), `no approval of old content is bound to today's: ${JSON.stringify(recs)}`);
    const state = JSON.parse(fs.readFileSync(path.join(r.ep, '.sdlc/state.json'), 'utf8'));
    assert.equal(state.steps.find((x) => x.id === 'architecture-review').status, 'in_review');
  } finally { r.done(); }
});

test('gate ci pre-merge: read-only — never pushes the review branch or the default branch (Path B)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  // CI checks out the review branch itself, just as a wired workflow would.
  git(ci, 'fetch', '-q', 'origin', 'review/EP-test/architecture');
  git(ci, 'checkout', '-q', '-B', 'review/EP-test/architecture', 'origin/review/EP-test/architecture');
  // Pre-merge the PR is approved + threads resolved but NOT yet merged → a held step. Under Path B
  // CI writes nothing: the platform PR is the source of truth during review.
  const r = await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: false, today: '2026-06-09', reader: () => ({ ...fullApproval, state: 'OPEN', merged: false }) });
  assert.equal(r.synced, 1, 'the predicate still ran (synced) — it just was not persisted');

  git(author, 'fetch', '-q', 'origin');
  // the REVIEW branch is untouched: HEAD is still the owner's artifact commit, no CI ledger commit.
  assert.equal(git(author, 'log', '-1', '--format=%s', 'origin/review/EP-test/architecture').toString().trim(), 'review: architecture (EP-test)');
  // no CI-written gate-state files exist on the review branch (review state lives on the platform).
  // state.json pre-exists from the seed; hub-prs/approvals/comments are CI-only — they must be absent.
  const tree = git(author, 'ls-tree', '-r', '--name-only', 'origin/review/EP-test/architecture').toString();
  assert.doesNotMatch(tree, /epics\/EP-test\/\.sdlc\/(hub-prs|approvals|comments)\.json/, 'no CI ledger pushed to the review branch');
  assert.doesNotMatch(tree, /epics\/EP-test\/reviews\//, 'no review summaries pushed to the review branch');
  // the DEFAULT branch is untouched too — its HEAD is still the seed.
  assert.equal(git(author, 'log', '-1', '--format=%s', 'origin/trunk').toString().trim(), 'seed');
  // and the read-only run leaves the CI checkout clean (the hub-prs seed is restored, nothing else).
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), '', 'pre-merge leaves a clean working tree');
  fs.rmSync(T, { recursive: true, force: true });
});

// The stampLegacyPr backfill used to run before gateCi knew the phase, so a pre-merge event naming a
// PR the ledger had not seen left approvals.json modified in the checkout — the run returned without
// committing it and without restoring it, breaking the documented "pre-merge writes nothing" guarantee
// and leaving a file `ledger-guard` rejects. It is now gated on `merged`: the file is not written at
// all pre-merge, so nothing has to be undone (a restore wide enough to cover approvals.json would also
// revert records the run never wrote — a human's uncommitted manual approval, or a freshly seeded
// ledger that `git clean` would delete outright).
test('gate ci pre-merge: never writes approvals.json for the legacy-PR backfill', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  // A review branch that DOES carry the ledger (an older Product, or the new-epic seed carve-out), holding
  // one approval from before approvals recorded which PR they arrived on.
  git(author, 'checkout', '-q', 'review/EP-test/architecture');
  const sdlc = path.join(author, 'epics/EP-test/.sdlc');
  fs.writeFileSync(path.join(sdlc, 'hub-prs.json'), JSON.stringify([
    { step: 'architecture-review', artifact: 'architecture.md', platform: 'github', number: 7, url: null, branch: 'review/EP-test/architecture', lastSyncedAt: null },
  ]));
  fs.writeFileSync(path.join(sdlc, 'approvals.json'), JSON.stringify([
    { artifact: 'architecture.md', step: 'architecture-review', approver: 'alice', role: 'owner', status: 'approved', date: '2026-06-01', source: 'bridge', artifactHash: 'sha256:old', approvedAt: '2026-06-01' },
  ], null, 2) + '\n');
  git(author, 'add', '-A');
  git(author, 'commit', '-q', '-m', 'review: architecture (EP-test) — carry the ledger');
  git(author, 'push', '-q', '-f', 'origin', 'review/EP-test/architecture');
  git(author, 'checkout', '-q', 'trunk');

  git(ci, 'fetch', '-q', 'origin', 'review/EP-test/architecture');
  git(ci, 'checkout', '-q', '-B', 'review/EP-test/architecture', 'origin/review/EP-test/architecture');
  // An UNCOMMITTED manual approval, the kind the yad-review-gate skill appends by hand. gateCi never
  // wrote it, so gateCi must not revert or delete it — the reason the fix is "don't write pre-merge"
  // rather than "git checkout the file afterwards".
  const approvalsFile = path.join(ci, 'epics/EP-test/.sdlc/approvals.json');
  const manual = JSON.parse(fs.readFileSync(approvalsFile, 'utf8'));
  manual.push({ artifact: 'architecture.md', step: 'architecture-review', approver: 'bob', role: 'reviewer', status: 'approved', date: '2026-06-08' });
  fs.writeFileSync(approvalsFile, JSON.stringify(manual, null, 2) + '\n');
  const onDisk = fs.readFileSync(approvalsFile, 'utf8');

  // A REPLACEMENT PR (#9, not the recorded #7) is what makes the backfill fire; not merged, so Path B
  // says this run persists nothing.
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 9, merged: false, today: '2026-06-09', reader: () => ({ ...fullApproval, state: 'OPEN', merged: false }) });
  assert.equal(fs.readFileSync(approvalsFile, 'utf8'), onDisk, 'pre-merge neither stamps nor reverts approvals.json');
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), 'M epics/EP-test/.sdlc/approvals.json', 'the only dirt is the human edit gateCi found');

  // The stamp is not lost, only deferred: the old pointer is still on disk, so the merge event records
  // it. (Run on the default branch, as the wired workflow does.)
  git(ci, 'checkout', '-q', '--', 'epics/EP-test/.sdlc/approvals.json');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');
  git(ci, 'checkout', '-q', 'origin/review/EP-test/architecture', '--', 'epics/EP-test/.sdlc');
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 9, merged: true, push: false, today: '2026-06-09', reader: () => fullApproval });
  // What the stamp buys is the `newerPr` proof: with `pr: 7` recorded, the approval arriving on #9 is
  // provably a NEW review, so it re-binds to the merged content instead of keeping the pre-edit hash and
  // reading `done` with zero live approvals (issue #156). Without the stamp, gateSync's own backfill
  // would write `pr: 9` first, the proof would never fire, and 'sha256:old' would survive.
  const stamped = JSON.parse(git(ci, 'show', 'HEAD:epics/EP-test/.sdlc/approvals.json').toString());
  // The approval now arrives under the LOGIN (`al`), which nothing on disk names — the older record says
  // `alice`, the roster's name for them (E62). It came from #7, so it is not the same review as the one on
  // #9 and is not adopted: the new record binds to the merged content, and the open step drops the old one.
  const al = stamped.find((a) => a.approver === 'al');
  assert.ok(al, 'the approval arriving on the replacement PR is recorded');
  assert.notEqual(al.artifactHash, 'sha256:old', 'a review on a new PR binds to the merged content, never the pre-edit hash');
  assert.ok(!stamped.some((a) => a.approver === 'alice' && a.source === 'bridge'), 'the older record from #7 is replaced, not kept beside it');
  fs.rmSync(T, { recursive: true, force: true });
});

test('gate ci --merged: advances the step + flips artifact status on the default branch (rebase-retries past the merge)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  // The human merge brings the review branch (the owner's artifact edit) onto the default
  // branch. This lands AFTER the CI clone took its trunk, so CI's advance push rebases and retries.
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');

  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: true, today: '2026-06-09', reader: () => fullApproval });

  git(author, 'fetch', '-q', 'origin');
  const state = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/state.json'));
  assert.equal(state.steps.find((s) => s.id === 'architecture-review').status, 'done');
  assert.equal(state.currentStep, 'ui-design');
  // CI wrote the closing record (E18): the merge, on the PR, on the run date when the platform gives none.
  const closed = state.steps.find((s) => s.id === 'architecture-review').closed;
  assert.deepEqual([closed.via, closed.pr, closed.date], ['merge', 7, '2026-06-09']);
  // the merged artifact is on trunk (via the human merge) and its status flipped to approved at merge.
  assert.equal(show(author, 'origin/trunk:epics/EP-test/contract.md'), BRANCH_CONTRACT);
  assert.match(show(author, 'origin/trunk:epics/EP-test/architecture.md'), /status: approved/);
  // the advance commit carries the loop guard.
  assert.match(git(author, 'log', '-1', '--format=%B', 'origin/trunk').toString(), /\[skip ci\]/);
  fs.rmSync(T, { recursive: true, force: true });
});

// issue #163, end to end: the wired sweep calls `gate ci --branch <ref> --pr <n> --merged` once per
// merged review PR/MR inside its 7-day window, every 15 minutes. On the buggy code each of those calls
// re-appended its own step's approvals at the tail of a shared approvals.json, so every call produced a
// reorder-only diff, committed it, and pushed it to the default branch — ~1,800 bot commits/day on the
// reporting Product. This walks that exact rotation and asserts the commit count stops growing.
test('gate ci --merged: a repeat sweep over two merged reviews commits nothing (issue #163)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  // Give the epic a SECOND review gate, so approvals.json holds more than one step's records.
  const statePath = path.join(author, 'epics/EP-test/.sdlc/state.json');
  const state = JSON.parse(fs.readFileSync(statePath));
  state.currentStep = 'epic-review';
  state.steps.unshift(
    { id: 'epic', type: 'author', artifact: 'epic.md', status: 'done', risk_tags: [] },
    { id: 'epic-review', type: 'review+approve', artifact: 'epic.md', status: 'in_review', risk_tags: [] },
  );
  fs.writeFileSync(statePath, JSON.stringify(state));
  git(author, 'add', '-A');
  git(author, 'commit', '-q', '-m', 'seed: second review gate');
  git(author, 'push', '-q', 'origin', 'trunk');
  // The human merges both reviews; CI then sweeps them on the default branch.
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');

  const sweep = async (day) => {
    for (const [base, pr] of [['epic', 8], ['architecture', 7]]) {
      await gateCi(ci, { branch: `review/EP-test/${base}`, pr, merged: true, today: day, reader: () => fullApproval });
    }
  };
  await sweep('2026-06-09'); // the advance itself — this one legitimately commits
  git(author, 'fetch', '-q', 'origin');
  const advanced = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/state.json'));
  assert.equal(advanced.steps.find((s) => s.id === 'epic-review').status, 'done');
  assert.equal(advanced.steps.find((s) => s.id === 'architecture-review').status, 'done');
  const approvals = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/approvals.json'));
  assert.equal(new Set(approvals.map((a) => a.step)).size, 2, 'both steps really are in one approvals.json');

  const count = () => git(ci, 'rev-list', '--count', 'HEAD').toString().trim();
  const settled = count();
  const ledger = show(author, 'origin/trunk:epics/EP-test/.sdlc/approvals.json');
  // Two more sweeps — the schedule firing again. Both steps are `done`, the platform state is
  // unchanged, so nothing may be written, committed or pushed.
  await sweep('2026-06-20');
  await sweep('2026-06-21');
  assert.equal(count(), settled, 'a repeat sweep of already-advanced reviews must not commit');
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), '', 'and must leave no working-tree churn');
  git(author, 'fetch', '-q', 'origin');
  assert.equal(show(author, 'origin/trunk:epics/EP-test/.sdlc/approvals.json'), ledger, 'approvals.json is byte-identical');
  fs.rmSync(T, { recursive: true, force: true });
});

// issue #362: two merged review MRs for ONE artifact (a re-review on a fresh MR, or per-story
// `stories-S01` / `stories-S02` branches, which all map to `stories/`). hub-prs.json holds one pointer
// per artifact, so on the buggy code each sweep visit moved it to its own MR — a real diff every time,
// committed as "advance … on merge" although the step was long done: 3 MRs × 96 sweeps = 288 commits/day.
test('gate ci --merged: a sweep over two merged MRs for one artifact commits nothing once the step is done (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');

  // The schedule lists every review MR merged in the window: the one that closed the step (#7) and
  // an older or later one for the same artifact (#9).
  const sweep = async (day) => {
    for (const pr of [7, 9]) {
      await gateCi(ci, { branch: 'review/EP-test/architecture', pr, merged: true, today: day, reader: () => fullApproval });
    }
  };
  await sweep('2026-06-09'); // the advance itself — this one legitimately commits
  git(author, 'fetch', '-q', 'origin');
  const advanced = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/state.json'));
  assert.equal(advanced.steps.find((s) => s.id === 'architecture-review').status, 'done');
  const subjects = () => git(ci, 'log', '--format=%s', 'HEAD').toString().split('\n').filter((l) => l.includes('on merge'));
  assert.equal(subjects().length, 1, 'one advance commit for one gate');

  const count = () => git(ci, 'rev-list', '--count', 'HEAD').toString().trim();
  const settled = count();
  const pointer = show(author, 'origin/trunk:epics/EP-test/.sdlc/product-prs.json');
  await sweep('2026-06-10');
  await sweep('2026-06-11');
  assert.equal(count(), settled, 'a repeat sweep must not commit a pointer flip');
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), '', 'and must leave no working-tree churn');
  git(author, 'fetch', '-q', 'origin');
  assert.equal(show(author, 'origin/trunk:epics/EP-test/.sdlc/product-prs.json'), pointer, 'the pointer never moves back to the older MR');
  assert.equal(JSON.parse(pointer).find((p) => p.artifact === 'architecture.md').number, 9, 'the newest review wins');
  fs.rmSync(T, { recursive: true, force: true });
});

// issue #362, the twin: the same flip while the step is NOT done (merged, but the approvals are not
// there yet). Each visit used to move the pointer to its own MR and commit a "sync" — the loop ran
// for the whole 7-day window just the same.
test('gate ci --merged: two merged MRs for one artifact do not flip the pointer while the step is open (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');

  const noApprovals = { ...fullApproval, reviews: [] };
  const sweep = async (day) => {
    for (const pr of [7, 9]) {
      await gateCi(ci, { branch: 'review/EP-test/architecture', pr, merged: true, today: day, reader: () => noApprovals });
    }
  };
  await sweep('2026-06-09');
  git(author, 'fetch', '-q', 'origin');
  const st = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/state.json'));
  assert.notEqual(st.steps.find((s) => s.id === 'architecture-review').status, 'done', 'no approvals: the step stays open');

  // Later days too: an unchanged open step used to re-stamp `lastSyncedAt` and write a fresh dated
  // approval record every day — one commit a day for the whole window.
  const count = () => git(ci, 'rev-list', '--count', 'HEAD').toString().trim();
  const settled = count();
  await sweep('2026-06-10');
  await sweep('2026-06-11');
  assert.equal(count(), settled, 'a repeat sweep must not commit a pointer flip on an open step');
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), '', 'and must leave no working-tree churn');
  git(author, 'fetch', '-q', 'origin');
  const ptr = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/product-prs.json'));
  assert.equal(ptr.find((p) => p.artifact === 'architecture.md').number, 9, 'the newest review wins');
  fs.rmSync(T, { recursive: true, force: true });
});

// issue #362 review: numbers come from creation order, merges happen in any order. A newer MR (#9)
// merged while still held must not block an OLDER one (#7) that merges later with the approvals the
// gate needs — the trial read lets #7 advance the step, and the sweep is quiet afterwards.
test('gate ci --merged: an older merged review that passes still advances past a held newer one (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');

  const reader = (_p, n) => (n === 7 ? fullApproval : { ...fullApproval, reviews: [] });
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 9, merged: true, today: '2026-06-09', reader });
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: true, today: '2026-06-09', reader });
  git(author, 'fetch', '-q', 'origin');
  const st = JSON.parse(show(author, 'origin/trunk:epics/EP-test/.sdlc/state.json'));
  assert.equal(st.steps.find((s) => s.id === 'architecture-review').status, 'done', 'the approved older review advances the gate');

  const count = () => git(ci, 'rev-list', '--count', 'HEAD').toString().trim();
  const sweep = async (day) => { for (const pr of [7, 9]) await gateCi(ci, { branch: 'review/EP-test/architecture', pr, merged: true, today: day, reader }); };
  // The first sweep moves the pointer forward to the newer #9 once — a newer review must be read, or a
  // re-review of a done step would be lost (#156) — and from then on nothing moves.
  const before = Number(count());
  await sweep('2026-06-10');
  assert.ok(Number(count()) - before <= 1, 'at most one commit: the pointer moves forward once');
  const settled = count();
  await sweep('2026-06-11');
  await sweep('2026-06-12');
  assert.equal(count(), settled, 'and the sweep settles once the step is done');
  assert.equal(git(ci, 'status', '--porcelain').toString().trim(), '', 'with no working-tree churn');
  fs.rmSync(T, { recursive: true, force: true });
});

// A mistyped `--pr` on the manual recovery must not become the pointer: numbers only grow, so a wrong
// high number would stay there and outrank every real review after it.
test('gate ci --merged: refuses a PR number that is not on the review branch (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');
  const before = git(ci, 'rev-list', '--count', 'HEAD').toString().trim();
  const branchOf = (_p, n) => ({ ok: true, branch: n === 97 ? 'review/EP-other/epic' : 'review/EP-test/architecture' });
  const prev = process.exitCode;
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 97, merged: true, today: '2026-06-09', reader: () => fullApproval, branchOf });
  assert.equal(process.exitCode, 1, 'a wrong number fails the run');
  process.exitCode = prev;
  assert.equal(git(ci, 'rev-list', '--count', 'HEAD').toString().trim(), before, 'and writes nothing');
  fs.rmSync(T, { recursive: true, force: true });
});

// The trial read of an older review: a failed platform read is "could not check", not "does not
// pass" — the run goes red and nothing moves. Its own verdict lines stay out of the log.
test('gate ci --merged: an older review whose read fails turns the run red and moves nothing (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');
  const reader = (_p, n) => (n === 7 ? { ok: false, reason: 'boom' } : { ...fullApproval, reviews: [] });
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 9, merged: true, today: '2026-06-09', reader });
  const prev = process.exitCode;
  process.exitCode = 0;
  const lines = [];
  const orig = console.log;
  console.log = (l) => lines.push(String(l));
  try {
    await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: true, today: '2026-06-09', reader });
  } finally { console.log = orig; }
  assert.equal(process.exitCode, 1, 'a failed read of the older review fails the run');
  process.exitCode = prev;
  const out = lines.join('\n');
  assert.match(out, /could not read PR #7 to check it against the gate/);
  assert.doesNotMatch(out, /does not pass the gate/, 'never "does not pass" for a review it could not read');
  assert.doesNotMatch(out, /boom read|PR #7, rule/, 'the trial prints nothing of its own');
  const ptr = JSON.parse(fs.readFileSync(path.join(ci, 'epics/EP-test/.sdlc/product-prs.json'), 'utf8'));
  assert.equal(ptr.find((p) => p.artifact === 'architecture.md').number, 9);
  fs.rmSync(T, { recursive: true, force: true });
});

// A Product that moved platform starts its numbering again: an old pointer from the other platform is
// not "newer", and the first move records a fresh URL and sync date, never the old review's.
test('gate ci --merged: a pointer from another platform never outranks a new review (issue #362)', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');
  git(ci, 'fetch', '-q', 'origin');
  git(ci, 'checkout', '-q', '-B', 'trunk', 'origin/trunk');
  const file = path.join(ci, 'epics/EP-test/.sdlc/product-prs.json');
  const platform = 'github'; // scaffoldCiProduct's Product platform
  const ptrs = [{ step: 'architecture-review', artifact: 'architecture.md', platform: platform === 'gitlab' ? 'github' : 'gitlab',
    number: 50, url: 'https://old.example/50', branch: 'review/EP-test/architecture', lastSyncedAt: '2026-01-01', nudged: ['al'] }];
  for (const f of ['product-prs.json', 'hub-prs.json']) fs.writeFileSync(path.join(ci, 'epics/EP-test/.sdlc', f), JSON.stringify(ptrs, null, 2) + '\n');
  git(ci, 'add', '-A');
  git(ci, 'commit', '-q', '-m', 'seed: pointer from the old platform');
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: true, today: '2026-06-09', reader: () => fullApproval });
  const now = JSON.parse(fs.readFileSync(file, 'utf8')).find((p) => p.artifact === 'architecture.md');
  assert.equal(now.number, 7, 'the new review is read, not the old platform\'s #50');
  assert.equal(now.platform, platform);
  assert.notEqual(now.url, 'https://old.example/50', 'the old review\'s URL is not carried to a new number');
  assert.ok(!(now.nudged || []).includes('al'), 'nor its nudges');
  assert.notEqual(now.lastSyncedAt, '2026-01-01', 'nor its sync date');
  const st = JSON.parse(fs.readFileSync(path.join(ci, 'epics/EP-test/.sdlc/state.json'), 'utf8'));
  assert.equal(st.steps.find((s) => s.id === 'architecture-review').status, 'done');
  fs.rmSync(T, { recursive: true, force: true });
});

// `yad gate ci … --merged` on the default branch is the DOCUMENTED manual recovery for a stuck gate,
// and a human's checkout is rarely pristine. Staging `git add -A -- epics/<e>` would sweep whatever
// else sits in that directory into a `chore(gate) … [skip ci]` commit pushed straight to the default
// branch — unreviewed, and contradicting the "CI commits only the ledger" contract.
test('gate ci --merged: commits the ledger allowlist only, never a dirty worktree', async () => {
  const { T, author, ci } = scaffoldCiProduct();
  git(author, 'checkout', '-q', 'trunk');
  git(author, 'merge', '-q', '--no-ff', 'review/EP-test/architecture', '-m', 'merge review/EP-test/architecture');
  git(author, 'push', '-q', 'origin', 'trunk');

  // The operator's checkout carries unrelated work inside the SAME epic directory: a half-finished
  // edit to a tracked artifact, and a stray untracked file.
  const ep = path.join(ci, 'epics/EP-test');
  fs.writeFileSync(path.join(ep, 'epic.md'), '---\nid: EP-test\nowner: alice\nrepos: [backend]\n---\nhalf-written thought\n');
  fs.writeFileSync(path.join(ep, 'scratch-notes.md'), 'do not ship me\n');

  // push: false — this is about what gets STAGED, and it keeps HEAD as the commit under inspection.
  await gateCi(ci, { branch: 'review/EP-test/architecture', pr: 7, merged: true, push: false, today: '2026-06-09', reader: () => fullApproval });

  const committed = git(ci, 'show', '--name-only', '--format=', 'HEAD').toString().trim().split('\n').filter(Boolean).sort();
  assert.deepEqual(committed, [
    'epics/EP-test/.sdlc/approvals.json',
    'epics/EP-test/.sdlc/comments.json',
    'epics/EP-test/.sdlc/hub-prs.json',
    // Written under BOTH names for one major, so CI commits both — see MIRRORED_FILES.
    'epics/EP-test/.sdlc/product-prs.json',
    'epics/EP-test/.sdlc/state.json',
    'epics/EP-test/architecture.md',
    'epics/EP-test/reviews/architecture--2026-06-09--approved.md',
  ], 'only the ledger, the generated review summary, and the status-flipped artifact');
  // The operator's work is untouched, still theirs to finish.
  const dirty = git(ci, 'status', '--porcelain').toString();
  assert.match(dirty, /epics\/EP-test\/epic\.md/, 'the unrelated artifact edit stays uncommitted');
  assert.match(dirty, /epics\/EP-test\/scratch-notes\.md/, 'the stray untracked file is neither committed nor cleaned');
  fs.rmSync(T, { recursive: true, force: true });
});

