test('hook: the Foundation ledger is protected under its fixed id, and its base seed is recognised (E75)', async () => {
  const { protectedLedgerPath, seededSlugs } = await import('./hook.mjs');
  assert.deepEqual(protectedLedgerPath('foundation/.sdlc/state.json'), { epic: 'EP-foundation', rel: 'foundation/.sdlc/state.json', kind: 'state' });
  assert.equal(protectedLedgerPath('foundation/.sdlc/hub-prs.json').kind, 'state');
  assert.equal(protectedLedgerPath('foundation/reviews/foundation--2026-09-13--comments.md').kind, 'review');
  assert.equal(protectedLedgerPath('foundation/scope.md'), null, 'a section is the author\'s, not CI\'s');
  assert.equal(protectedLedgerPath('foundationx/.sdlc/state.json'), null, 'a folder that merely starts with the name');
  // The base listing now spans both folders, and the Foundation's ledger folds to its id — so an edit to
  // an on-base Foundation is a mutation, not a creation.
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-hook-foundation-'));
  try {
    const calls = [];
    const runner = (cmd, args = []) => {
      calls.push(args.join(' '));
      const line = args.join(' ');
      if (line.includes('symbolic-ref')) return { ok: true, stdout: 'origin/main', code: 0 };
      if (line.includes('rev-parse --verify')) return { ok: true, stdout: '', code: 0 };
      if (line.includes('ls-tree')) return { ok: true, code: 0, stdout: ['epics/EP-a/.sdlc/state.json', 'foundation/.sdlc/state.json', 'foundation/scope.md'].join('\0') };
      return { ok: false, stdout: '', code: 1 };
    };
    // …and, with a Foundation on base, `ep-discovery` too: a fresh old-spelling ledger would be a second
    // product level, not a new epic.
    assert.deepEqual([...seededSlugs(T, {}, runner)].sort(), ['ep-a', 'ep-discovery', 'ep-foundation']);
    assert.ok(calls.some((c) => / -- epics foundation$/.test(c)), `ls-tree must list foundation too: ${calls.join(' | ')}`);
  } finally { fs.rmSync(T, { recursive: true, force: true }); }
});

test('doctor: a verified Product with a Foundation is warned when its wired checks predate foundation/ (E75)', async () => {
  const { foundationChecks, collectDoctor } = await import('./doctor.mjs');
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-foundation-guard-'));
  const run = () => { const checks = []; foundationChecks(checks, T); return checks; };
  const tpl = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
  try {
    fs.mkdirSync(path.join(T, '.sdlc'), { recursive: true });
    fs.mkdirSync(path.join(T, 'checks'), { recursive: true });
    fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({ platform: 'github', ledger: 'verified' }));
    // The copy a 3.18.1 Product has committed — it knows `epics/` only.
    fs.writeFileSync(path.join(T, 'checks/ledger-guard.sh'), tpl('cli/fixtures/ledger-guard-v3.18.1.sh'));
    fs.writeFileSync(path.join(T, 'checks/pr-title.sh'), tpl('skills/yad-pr-template/templates/checks/pr-title.sh'));
    assert.deepEqual(run(), [], 'no Foundation — nothing to guard, nothing to say');

    fs.mkdirSync(path.join(T, 'foundation/.sdlc'), { recursive: true });
    const [w] = run();
    assert.equal(w?.id, 'foundation:guard');
    assert.equal(w.status, 'warn');
    assert.match(w.message, /checks\/ledger-guard\.sh does not know `foundation\/`/);
    assert.doesNotMatch(w.message, /pr-title/, 'the refreshed PR gate is not named');
    assert.match(w.hint, /yad update/);
    assert.ok(collectDoctor(T).checks.some((x) => x.id === 'foundation:guard'), 'wired into yad doctor, not just exported');

    fs.writeFileSync(path.join(T, 'checks/ledger-guard.sh'), tpl('skills/yad-checks/templates/checks/ledger-guard.sh'));
    assert.deepEqual(run(), [], 'the current templates guard it');

    fs.writeFileSync(path.join(T, 'checks/ledger-guard.sh'), tpl('cli/fixtures/ledger-guard-v3.18.1.sh'));
    fs.writeFileSync(path.join(T, '.sdlc/hub.json'), JSON.stringify({ platform: 'github', ledger: 'local' }));
    assert.deepEqual(run(), [], 'a local ledger is written by humans on purpose');
  } finally { fs.rmSync(T, { recursive: true, force: true }); }
});

// ---- `yad foundation new` — the engine seeds the Product level (E75) -----------------------------
async function foundationNewOn({ files = {}, json = false } = {}) {
  const { runFoundationNew } = await import('./epic.mjs');
  const T = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-e75-'));
  fs.mkdirSync(path.join(T, '.sdlc'), { recursive: true });
  for (const [rel, body] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(T, rel)), { recursive: true });
    fs.writeFileSync(path.join(T, rel), body);
  }
  const code = process.exitCode;
  process.exitCode = undefined;
  const out = await grab(() => runFoundationNew(T, { today: '2026-09-13', json }));
  const failed = process.exitCode === 1;
  process.exitCode = code;
  return { T, out, failed };
}

test('yad foundation new: refuses on a verified Product whose wired checks predate the Foundation (E75 follow-up)', async () => {
  const verifiedProduct = JSON.stringify({ platform: 'github', ledger: 'verified' });
  const oldGuard = '#!/usr/bin/env bash\ncase "$f" in\n  epics/*) ;;\nesac\n';
  const stale = await foundationNewOn({ files: { '.sdlc/hub.json': verifiedProduct, 'checks/ledger-guard.sh': oldGuard } });
  try {
    assert.equal(stale.failed, true, stale.out);
    assert.match(stale.out, /wired checks predate the Foundation: checks\/ledger-guard\.sh does not know foundation\//);
    assert.match(stale.out, /yad update/);
    assert.equal(fs.existsSync(path.join(stale.T, 'foundation')), false, 'nothing is seeded');
  } finally { fs.rmSync(stale.T, { recursive: true, force: true }); }
  // The same old check on a LOCAL ledger guards nothing either way, so it is not a reason to refuse.
  const local = await foundationNewOn({ files: { '.sdlc/hub.json': JSON.stringify({ platform: 'github' }), 'checks/ledger-guard.sh': oldGuard } });
  try { assert.equal(local.failed, false, local.out); } finally { fs.rmSync(local.T, { recursive: true, force: true }); }
  // And a verified Product whose check knows the folder seeds as normal.
  const fresh = await foundationNewOn({ files: { '.sdlc/hub.json': verifiedProduct, 'checks/ledger-guard.sh': 'case "$f" in\n      foundation/*) ;;\nesac\n' } });
  try { assert.equal(fresh.failed, false, fresh.out); } finally { fs.rmSync(fresh.T, { recursive: true, force: true }); }
});

test('yad foundation new: writes the Foundation ledger in foundation/, and nothing under epics/', async () => {
  const { T, out, failed } = await foundationNewOn();
  try {
    assert.equal(failed, false, out);
    const dir = path.join(T, 'foundation');
    const state = JSON.parse(fs.readFileSync(path.join(dir, '.sdlc', 'state.json'), 'utf8'));
    assert.equal(state.schemaVersion, ENGINE_SHAPE, 'stamped by the one writer');
    assert.equal(state.epicId, 'EP-foundation');
    assert.equal(state.kind, 'foundation');
    assert.equal(state.profile, 'foundation');
    assert.equal('type' in state, false, 'the product level is not a work item');
    assert.deepEqual(state.steps.map((s) => s.id), ['foundation', 'foundation-review']);
    assert.deepEqual(JSON.parse(fs.readFileSync(path.join(dir, '.sdlc', 'approvals.json'), 'utf8')), []);
    assert.ok(fs.statSync(path.join(dir, 'reviews')).isDirectory());
    assert.equal(fs.existsSync(path.join(T, 'epics')), false);
    assert.equal(fs.readdirSync(dir).filter((f) => f.endsWith('.md')).length, 0, 'no section is written — they are authored');
    assert.match(out, /EP-foundation seeded/);
    assert.match(out, /run the yad-discovery skill to author foundation\//);
    assert.match(out, /yad gate open EP-foundation foundation\//);
  } finally { cleanTmp(T); }
});

test('yad foundation new --json names the sections, and a second run refuses', async () => {
  const { T, out } = await foundationNewOn({ json: true });
  try {
    const j = JSON.parse(out);
    assert.equal(j.ok, true);
    assert.deepEqual(j.sections, {
      required: ['purpose.md', 'scope.md', 'mvp.md', 'roadmap.md', 'stack.md', 'repos.md'],
      optional: ['market.md', 'risks.md'],
    });
    const { runFoundationNew } = await import('./epic.mjs');
    const before = fs.readFileSync(path.join(T, 'foundation/.sdlc/state.json'), 'utf8');
    const code = process.exitCode;
    const again = await grab(() => runFoundationNew(T, { today: '2026-09-14' }));
    assert.equal(process.exitCode, 1);
    process.exitCode = code;
    assert.match(again, /already has its Foundation/);
    assert.equal(fs.readFileSync(path.join(T, 'foundation/.sdlc/state.json'), 'utf8'), before, 'nothing overwritten');
  } finally { cleanTmp(T); }
});

// ---- `yad foundation status` — roadmap features read from the epic ledgers (E76 follow-up) -------------

test('roadmapFeatures: reads every feature table by its Proposed epic id column, in either spelling (E76 follow-up)', async () => {
  const { roadmapFeatures } = await import('./epic-state.mjs');
  const text = [
    '---', 'id: EP-foundation', 'artifact: roadmap', 'status: approved', 'owner: sam', '---', '',
    '## Summary', 'Words. | not a table', '',
    '## Phase 1 — MVP',
    '| Feature | Proposed epic id | Status |',
    '|---------|------------------|--------|',
    '<!-- one row per feature, e.g. | Registration | EP-registration | planned | -->',
    '| Flats and invites | `EP-flat-invites` | planned |',
    '|  |  |  |',
    'Log and split | EP-log-expense |',
    '## Phase 2 — Old layout',
    '| Proposed epic id | Requirements | Feature | Status |',
    '| --- | --- | --- | --- |',
    '| EP-recurring | F-01 | Recurring bills | epic-started |',
    '',
    '| Risk | Why |', '|---|---|', '| a | b |',
  ].join('\r\n');
  assert.deepEqual(roadmapFeatures(text), [
    { phase: 'Phase 1 — MVP', feature: 'Flats and invites', epicId: 'EP-flat-invites', written: 'planned' },
    { phase: 'Phase 1 — MVP', feature: 'Log and split', epicId: 'EP-log-expense', written: null },
    { phase: 'Phase 2 — Old layout', feature: 'Recurring bills', epicId: 'EP-recurring', written: 'epic-started' },
  ], 'a comment row does not end a table, a heading right after a table is still a phase, and a table with no id column is not a roadmap');
  assert.deepEqual(roadmapFeatures('| Feature | Status |\n|---|---|\n| A | planned |\n'), [], 'no Proposed epic id column, no features');
  assert.deepEqual(roadmapFeatures(''), []);
  // Both shipped templates, as written, hold no feature — their example rows are comments.
  const src = fs.readFileSync(path.join(ROOT, 'skills/yad-discovery/references/foundation-schema.md'), 'utf8');
  const tpl = src.match(/^### `roadmap\.md`[^\n]*\n\n```markdown\n([\s\S]*?)\n```/m)[1];
  assert.deepEqual(roadmapFeatures(tpl), [], 'the roadmap template reads as no features');
  const example = src.match(/^### `roadmap\.md`[\s\S]*?\*\*Example \(Tally\):\*\*\n\n```markdown\n([\s\S]*?)\n```/m)[1];
  assert.deepEqual(roadmapFeatures(example).map((f) => f.epicId), ['EP-flat-invites', 'EP-log-expense', 'EP-settle-up', 'EP-recurring-bills'],
    'the worked example reads as its four features');
});

test('featureStatus: planned, in-shape, in-build and shipped come from the ledger, through the reader yad next uses (E76 follow-up)', async () => {
  const { featureStatus, FEATURE_STATUSES } = await import('./epic-state.mjs');
  // The vocabulary is a promise to scripts reading `--json`, written in two places: the constant and the
  // CLI reference. Nothing else ties them, so a word added to one and not the other would drift silently.
  const cliRow = fs.readFileSync(path.join(ROOT, 'docs/CLI.md'), 'utf8').split('\n').find((l) => l.startsWith('| `yad foundation status'));
  assert.deepEqual(FEATURE_STATUSES.filter((w) => cliRow.includes(`\`${w}\` (`)), FEATURE_STATUSES, 'docs/CLI.md explains every status the engine can report');
  assert.deepEqual([...cliRow.matchAll(/`([a-z-]+)` \(/g)].map((m) => m[1]).filter((w) => /^(planned|in-|shipped)/.test(w)), FEATURE_STATUSES,
    'and names no other, in the same order');
  const step = (id, type, status) => ({ id, type, artifact: `${id}.md`, status, risk_tags: [] });
  const shape = { epicId: 'EP-a', currentStep: 'architecture', steps: [step('epic', 'author', 'done'), step('epic-review', 'review+approve', 'done'), step('architecture', 'author', 'in_progress')] };
  const built = { epicId: 'EP-a', currentStep: 'ready-for-build', steps: [step('epic', 'author', 'done'), step('epic-review', 'review+approve', 'done')] };
  const lane = (done) => ({ currentStep: 'engineer-review', steps: [{ id: 'spec', status: 'done' }, { id: 'engineer-review', status: done ? 'done' : 'in_progress' }] });
  const L = (state, buildStates = []) => ({ state, approvals: [], comments: [], productPrs: [], buildStates });
  assert.equal(featureStatus(L(null)), 'planned');
  assert.equal(featureStatus(undefined), 'planned');
  assert.equal(featureStatus(L(shape)), 'in-shape');
  assert.equal(featureStatus(L(built)), 'in-build', 'Shape done, no Build recorded yet');
  assert.equal(featureStatus(L(built, [{ story: 'EP-a-S01', repos: {} }])), 'in-build', 'a story with no lanes has shipped nothing');
  assert.equal(featureStatus(L(built, [{ story: 'EP-a-S01', repos: { api: lane(true), web: lane(false) } }])), 'in-build', 'one lane still moving');
  assert.equal(featureStatus(L(built, [{ story: 'EP-a-S01', repos: { api: lane(true) } }, { story: 'EP-a-S02', repos: { web: lane(true) } }])), 'shipped');
  const stub = { epicId: 'EP-old', kind: 'stub', currentStep: 'backfill-pending', steps: [step('epic', 'author', 'todo')] };
  assert.equal(featureStatus(L(stub)), 'shipped', 'a brownfield anchor is a feature that shipped before the Product');
});

