    fs.mkdirSync(path.join(fx.T, 'epics/EP-Legacy/.sdlc'), { recursive: true });
    fx.write('epics/EP-Legacy/.sdlc/approvals.json', [{ approver: 'legacy-reviewer', date: daysBefore(P_TODAY, 1) }]);
    const r = activePeople(fx.T, { today: P_TODAY });
